import java.util.Scanner;

public class Main {
    public static int maxOf(int a, int b) {
        return a > b ? a : b;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int best = sc.nextInt();
        for (int i = 1; i < 3; i++) {
            best = maxOf(best, sc.nextInt());
        }

        System.out.println("最大的那个是 " + best + " 喵");
    }
}

