import java.util.Scanner;

public class Main {
    public static int sumTo(int n) {
        int total = 0;
        for (int i = 1; i <= n; i++) {
            total = total + i;
        }
        return total;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int all = 0;
        for (int i = 0; i < 2; i++) {
            all = all + sumTo(sc.nextInt());
        }

        System.out.println("一共 " + all + " 条喵");
    }
}

